<?php
declare(strict_types=1);
require __DIR__ . '/../includes/db.php';
if (empty($_SESSION['blog_admin_id'])) { header('Location: login.php'); exit; }
if (empty($_SESSION['csrf'])) $_SESSION['csrf']=bin2hex(random_bytes(32));
$csrf=(string)$_SESSION['csrf'];$error='';$notice='';
function avf_h($v):string{return htmlspecialchars((string)($v??''),ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!hash_equals($csrf,(string)($_POST['csrf']??'')))$error='Phiên đã hết hạn. Hãy tải lại trang.';
 else{
  $action=(string)($_POST['action']??'');
  try{
   if($action==='save'){
    $id=(int)($_POST['id']??0);$name=trim((string)($_POST['name']??''));$url=trim((string)($_POST['image_url']??''));$rarity=(string)($_POST['rarity']??'common');$description=trim((string)($_POST['description']??''));$sort=(int)($_POST['sort_order']??0);
    if(mb_strlen($name)<2||mb_strlen($name)>100)$error='Tên khung cần từ 2 đến 100 ký tự.';
    elseif(!preg_match('~^(https?://|/)~i',$url)||mb_strlen($url)>500)$error='Đường dẫn ảnh cần là URL http(s) hoặc đường dẫn bắt đầu bằng /.';
    elseif(!in_array($rarity,['common','rare','epic','legendary','mythic'],true))$error='Cấp độ khung không hợp lệ.';
    else{
     if($id>0){$q=$pdo->prepare('UPDATE avatar_frames SET name=?,image_url=?,rarity=?,description=?,sort_order=? WHERE id=?');$q->execute([$name,$url,$rarity,$description,$sort,$id]);$notice='Đã cập nhật khung avatar.';}
     else{$q=$pdo->prepare('INSERT INTO avatar_frames(name,image_url,rarity,description,sort_order) VALUES(?,?,?,?,?)');$q->execute([$name,$url,$rarity,$description,$sort]);$notice='Đã thêm khung avatar mới.';}
    }
   }elseif($action==='grant'){
    $memberId=(int)($_POST['member_id']??0);$frameId=(int)($_POST['frame_id']??0);
    if($memberId<1||$frameId<1)$error='Hãy nhập ID thành viên và chọn khung.';
    else{$q=$pdo->prepare('SELECT id FROM members WHERE id=? AND is_active=1');$q->execute([$memberId]);if(!$q->fetchColumn())$error='Không tìm thấy thành viên đang hoạt động.';else{$q=$pdo->prepare('INSERT IGNORE INTO member_avatar_frames(member_id,frame_id,granted_by) VALUES(?,?,?)');$q->execute([$memberId,$frameId,(int)$_SESSION['blog_admin_id']]);$notice=$q->rowCount()?'Đã cấp khung cho thành viên.':'Thành viên đã sở hữu khung này.';}}
   }elseif($action==='toggle'){
    $id=(int)($_POST['id']??0);$pdo->prepare('UPDATE avatar_frames SET is_active=IF(is_active=1,0,1) WHERE id=?')->execute([$id]);$notice='Đã cập nhật trạng thái khung.';
   }elseif($action==='delete'){
    $id=(int)($_POST['id']??0);$q=$pdo->prepare('SELECT COUNT(*) FROM member_avatar_frames WHERE frame_id=?');$q->execute([$id]);if((int)$q->fetchColumn()>0)$error='Khung đã được cấp cho thành viên nên không thể xóa. Hãy tắt hoạt động thay thế.';else{$pdo->prepare('DELETE FROM avatar_frames WHERE id=?')->execute([$id]);$notice='Đã xóa khung avatar.';}
   }else $error='Thao tác không hợp lệ.';
  }catch(Throwable $e){$error='Chưa cài đặt database khung avatar hoặc dữ liệu không hợp lệ. Hãy chạy database/avatar_frames.sql.';}
 }
}
$frames=[];$setupError=false;
try{$frames=$pdo->query("SELECT f.*, (SELECT COUNT(*) FROM member_avatar_frames o WHERE o.frame_id=f.id) owned_count FROM avatar_frames f ORDER BY f.sort_order,f.id DESC")->fetchAll(PDO::FETCH_ASSOC);}catch(Throwable $e){$setupError=true;}
$rarityNames=['common'=>'Thường','rare'=>'Hiếm','epic'=>'Sử thi','legendary'=>'Huyền thoại','mythic'=>'Thần thoại'];
?>
<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Quản lý khung avatar | Truyện Đêm</title><link rel="stylesheet" href="../css/style.css"><link rel="stylesheet" href="../css/admin-white.css"><style>
.avf-main{max-width:1120px;margin:26px auto;padding:0 18px 60px;color:#263044}.avf-head,.avf-card,.avf-form{background:#fff;border:1px solid #e5e9f0;border-radius:15px;padding:18px;margin-bottom:16px;box-shadow:0 3px 12px #18233a08}.avf-head h1{margin:0 0 6px}.avf-head p{margin:0;color:#748096}.avf-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:14px}.avf-form label{display:block;font-size:.82rem;font-weight:700;margin:10px 0}.avf-form input,.avf-form select,.avf-form textarea{display:block;width:100%;box-sizing:border-box;padding:10px;border:1px solid #d7dce5;border-radius:8px;margin-top:5px}.avf-btn{border:0;border-radius:8px;padding:10px 13px;background:#69418d;color:white;font-weight:700;cursor:pointer}.avf-btn.secondary{background:#526174}.avf-btn.danger{background:#b44450}.avf-actions{display:flex;gap:7px;flex-wrap:wrap;margin-top:12px}.avf-preview{width:74px;height:74px;object-fit:contain;display:block;margin-bottom:10px}.avf-muted{font-size:.78rem;color:#7b8495}.avf-flash{padding:11px;border-radius:9px;background:#e7f6ed;color:#23633b;margin:12px 0}.avf-error{background:#fff0f0;color:#a32d36}.avf-inline{display:inline}.avf-grant{display:grid;grid-template-columns:1fr 1fr auto;gap:8px;align-items:end}@media(max-width:600px){.avf-main{padding:0 12px 45px}.avf-grant{grid-template-columns:1fr}.avf-card,.avf-form{padding:14px}}
</style></head><body><main class="avf-main"><header class="avf-head"><span>TRUYỆN ĐÊM · CMS</span><h1>Quản lý khung avatar</h1><p>Thêm mẫu PNG nền trong suốt, thiết lập độ hiếm và trao tặng khung cho thành viên.</p><p><a href="index.php">← Quay lại quản trị</a></p></header>
<?php if($notice):?><div class="avf-flash"><?=avf_h($notice)?></div><?php endif;?><?php if($error):?><div class="avf-flash avf-error"><?=avf_h($error)?></div><?php endif;?><?php if($setupError):?><div class="avf-flash avf-error">Chưa có bảng dữ liệu. Hãy chạy database/avatar_frames.sql trong phpMyAdmin.</div><?php endif;?>
<div class="avf-grid"><section class="avf-form"><h2>＋ Thêm khung mới</h2><form method="post"><input type="hidden" name="csrf" value="<?=avf_h($csrf)?>"><input type="hidden" name="action" value="save"><label>Tên khung<input name="name" maxlength="100" required></label><label>URL ảnh khung PNG<input name="image_url" maxlength="500" placeholder="/uploads/avatar-frames/thien-kieu.png" required></label><label>Độ hiếm<select name="rarity"><?php foreach($rarityNames as $k=>$v):?><option value="<?=avf_h($k)?>"><?=avf_h($v)?></option><?php endforeach;?></select></label><label>Mô tả<textarea name="description" maxlength="255"></textarea></label><label>Thứ tự<input type="number" name="sort_order" value="0"></label><button class="avf-btn">Thêm khung</button></form></section>
<section class="avf-form"><h2>✦ Trao khung cho thành viên</h2><form method="post" class="avf-grant"><input type="hidden" name="csrf" value="<?=avf_h($csrf)?>"><input type="hidden" name="action" value="grant"><label>ID thành viên<input type="number" name="member_id" min="1" required placeholder="Ví dụ: 25"></label><label>Khung avatar<select name="frame_id" required><option value="">Chọn khung</option><?php foreach($frames as $f):?><option value="<?=(int)$f['id']?>"><?=avf_h($f['name'])?></option><?php endforeach;?></select></label><button class="avf-btn">Cấp khung</button></form><p class="avf-muted">Có thể xem ID thành viên trong trang quản lý thành viên. Cấp trùng sẽ không tạo bản ghi trùng.</p></section></div>
<section class="avf-card"><h2>Danh sách khung (<?=count($frames)?>)</h2><?php if(!$frames):?><p class="avf-muted">Chưa có khung nào. Thêm mẫu đầu tiên ở biểu mẫu bên trên.</p><?php else:?><div class="avf-grid"><?php foreach($frames as $f):?><article class="avf-card"><img class="avf-preview" src="<?=avf_h($f['image_url'])?>" alt=""><strong><?=avf_h($f['name'])?></strong><p class="avf-muted"><?=avf_h($rarityNames[$f['rarity']]??'') ?> · <?= (int)$f['owned_count']?> thành viên sở hữu · <?=((int)$f['is_active']===1?'Đang mở':'Đang khóa')?></p><form method="post" class="avf-form"><input type="hidden" name="csrf" value="<?=avf_h($csrf)?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=(int)$f['id']?>"><label>Tên<input name="name" value="<?=avf_h($f['name'])?>" required></label><label>URL ảnh<input name="image_url" value="<?=avf_h($f['image_url'])?>" required></label><label>Độ hiếm<select name="rarity"><?php foreach($rarityNames as $k=>$v):?><option value="<?=avf_h($k)?>" <?=($f['rarity']===$k?'selected':'')?>><?=avf_h($v)?></option><?php endforeach;?></select></label><label>Mô tả<textarea name="description"><?=avf_h($f['description'])?></textarea></label><label>Thứ tự<input type="number" name="sort_order" value="<?=(int)$f['sort_order']?>"></label><div class="avf-actions"><button class="avf-btn">Lưu sửa đổi</button></form><form method="post" class="avf-inline"><input type="hidden" name="csrf" value="<?=avf_h($csrf)?>"><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?=(int)$f['id']?>"><button class="avf-btn secondary"><?=((int)$f['is_active']===1?'Tắt':'Mở')?> khung</button></form><form method="post" class="avf-inline" onsubmit="return confirm('Xóa khung avatar này?')"><input type="hidden" name="csrf" value="<?=avf_h($csrf)?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=(int)$f['id']?>"><button class="avf-btn danger">Xóa</button></form></div></article><?php endforeach;?></div><?php endif;?></section></main></body></html>
